//! Call-domain identifiers. Every identifier is generated by CF Meet; no provider room,
//! SIP dialog, carrier call or provider request identifier is ever used as one.

use std::fmt;

use rand::{rngs::OsRng, RngCore};
use serde::Serialize;

typed_id!(
    /// Canonical identity of a logical Call, whatever network or provider executes it.
    CallId
);
typed_id!(
    /// A logical participant of one Call.
    CallParticipantId
);
typed_id!(
    /// One device / network participation of one participant.
    CallSessionId
);
typed_id!(
    /// One connected period of one session.
    CallSessionIntervalId
);
typed_id!(
    /// A provider-independent routing decision of one Call.
    CallRouteId
);
typed_id!(
    /// A canonical Calling-side leg of one Call.
    CallLegId
);
typed_id!(
    /// One attempt of one Call.
    CallAttemptId
);
typed_id!(
    /// A persisted authorization decision for one Call.
    CallAuthorizationId
);
typed_id!(
    /// An immutable call event.
    CallEventId
);
typed_id!(
    /// A provider-independent quality record.
    CallQualityRecordId
);
typed_id!(
    /// A provider-independent usage record.
    CallUsageRecordId
);
typed_id!(
    /// A transactional outbox row.
    OutboxEventId
);

typed_id!(
    /// The ring offer of one Call to one application endpoint.
    CallInvitationId
);
typed_id!(
    /// The single winning answer of one logical participant.
    CallAnswerClaimId
);
typed_id!(
    /// Server-authoritative media permissions of one participant.
    MediaPermissionsId
);
typed_id!(
    /// The Calling-private binding of a Call to its media provider resource.
    CallMediaSessionId
);
typed_id!(
    /// An idempotent Calling command record.
    CallCommandId
);
typed_id!(
    /// An application-to-application transfer of one Call.
    CallTransferId
);
typed_id!(
    /// A recorded, authenticated media-provider callback.
    MediaProviderEventId
);

impl CallEventId {
    /// Envelope form (`evt_<32 hex>`, contract `cfmeet.platform.event-envelope`).
    pub fn envelope_id(&self) -> String {
        format!("evt_{}", self.as_uuid().simple())
    }
}

/// Server-generated media / signaling identity of a call session: `cfmid_` followed by
/// 256 bits from the operating system CSPRNG, hex encoded. Opaque, globally unique (also
/// database-enforced) and provider-neutral: it is never a provider participant identity,
/// browser id, telephone number or customer user id, and it can never be chosen by a
/// client — there is no constructor from external input.
#[derive(Clone, PartialEq, Eq, Hash, Serialize)]
#[serde(transparent)]
pub struct MediaIdentity(String);

impl MediaIdentity {
    pub const PREFIX: &'static str = "cfmid_";

    pub(crate) fn generate() -> Self {
        let mut bytes = [0u8; 32];
        OsRng.fill_bytes(&mut bytes);
        Self(format!("{}{}", Self::PREFIX, hex::encode(bytes)))
    }

    /// Re-hydrates a persisted identity (database rows only).
    pub(crate) fn from_persisted(value: String) -> Self {
        Self(value)
    }

    pub fn as_str(&self) -> &str {
        &self.0
    }

    /// Whether `value` has the shape of a server-generated identity.
    pub fn is_well_formed(value: &str) -> bool {
        value.strip_prefix(Self::PREFIX).is_some_and(|hex| {
            hex.len() == 64 && hex.bytes().all(|b| matches!(b, b'0'..=b'9' | b'a'..=b'f'))
        })
    }
}

impl fmt::Debug for MediaIdentity {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        // Enough to correlate in diagnostics, never the full signaling identity.
        write!(f, "MediaIdentity({}…)", &self.0[..self.0.len().min(14)])
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn media_identities_are_well_formed_and_unique() {
        let a = MediaIdentity::generate();
        let b = MediaIdentity::generate();
        assert!(MediaIdentity::is_well_formed(a.as_str()));
        assert_eq!(a.as_str().len(), 6 + 64);
        assert_ne!(a, b);
        assert!(!format!("{a:?}").contains(&a.as_str()[20..]));
        for bad in ["", "cfmid_", "cfmid_XYZ", "+2348012345678", "user-123"] {
            assert!(!MediaIdentity::is_well_formed(bad), "{bad}");
        }
    }

    #[test]
    fn envelope_event_ids_follow_the_contract() {
        let id = CallEventId::generate();
        let e = id.envelope_id();
        assert!(e.starts_with("evt_"));
        assert_eq!(e.len(), 36);
        assert!(e[4..]
            .bytes()
            .all(|b| b.is_ascii_hexdigit() && !b.is_ascii_uppercase()));
    }
}
